const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;gap:6px;padding:8px;overflow:hidden;color:var(--ink);font-family:-apple-system,\"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",system-ui,sans-serif;font-size:13px;line-height:1.4}\n.card *{box-sizing:border-box}\n.card button,.card textarea{font:inherit;color:inherit;-webkit-tap-highlight-color:transparent}\n.card button{cursor:pointer}\n.card button:focus-visible,.card textarea:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.card button:disabled{opacity:.5;cursor:default}\n\n.tabs{flex:none;display:flex;gap:4px}\n.tab{flex:1 1 0;min-width:0;height:28px;padding:0 4px;border-radius:999px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tab.on{background:var(--accent);color:var(--on-accent);border-color:transparent}\n.tab .n{display:inline-block;margin-left:4px;min-width:16px;padding:0 4px;border-radius:99px;background:var(--accent);color:var(--on-accent);font-size:10px;line-height:16px}\n.tab.on .n{background:var(--on-accent);color:var(--accent)}\n\n.body{flex:1 1 auto;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.err{flex:none;padding:4px 8px;border-radius:8px;border:1px solid var(--ink);background:var(--panel-paper);font-size:12px;font-weight:600}\n.note{padding:5px 8px;border-radius:8px;background:var(--soft);font-size:12px}\n\n.prog{flex:none;display:flex;align-items:center;gap:8px;min-height:18px;font-size:11px;color:var(--muted)}\n.ptxt{flex:none;white-space:nowrap}\n.bar{flex:1;min-width:20px;height:4px;border-radius:99px;background:var(--soft);overflow:hidden;display:block}\n.bar b{display:block;height:100%;background:var(--accent);border-radius:99px}\n.link{flex:none;background:none;border:0;padding:2px 4px;font-size:11px;color:var(--ink);text-decoration:underline;white-space:nowrap}\n\n.flash{flex:1 1 auto;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px;overflow:auto;padding:10px;border-radius:14px;border:1px solid var(--line);background:var(--panel-paper)}\n.flash:not(.flipped){cursor:pointer}\n.face{margin:auto 0;min-width:0}\n.fq{width:100%}\n.face .tag,.dsec .tag{display:block;margin-bottom:2px;font-size:10px;letter-spacing:.08em;color:var(--muted)}\n.txt{font-size:15px;font-weight:600;line-height:1.45;white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word}\n.hint{font-size:11px;color:var(--muted);text-align:center}\n.flash.flipped .fq .txt{font-size:12px;font-weight:500;color:var(--muted)}\n.fa{padding:8px 10px;border-radius:10px;background:var(--soft);animation:flipin .28s ease-out;transform-origin:top center}\n.fa .txt{font-size:15px}\n@keyframes flipin{from{transform:rotateX(-80deg);opacity:0}to{transform:rotateX(0);opacity:1}}\n@media (prefers-reduced-motion:reduce){.fa{animation:none}}\n\n.acts{flex:none;display:flex;align-items:stretch;gap:6px;min-width:0}\n.btn{min-width:0;min-height:36px;padding:0 10px;border-radius:10px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);font-size:13px;font-weight:600;white-space:nowrap}\n.btn.grow{flex:1 1 0}\n.btn.main{background:var(--accent);color:var(--on-accent);border-color:transparent}\n.btn.strong{border-color:var(--ink);font-weight:700}\n.ask{flex:none;align-self:center;font-size:12px;font-weight:600}\n.rate{flex:1 1 0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;min-height:42px;padding:3px 2px;overflow:hidden}\n.rate .rl{font-size:12px;font-weight:700}\n.rate .rs{font-size:10px}\n.rate.again{background:transparent}\n.rate.again .rs{color:var(--muted)}\n.rate.hard{background:var(--soft)}\n.rate.good{background:var(--accent);color:var(--on-accent);border-color:transparent}\n\n.lhead{flex:none;display:flex;align-items:center;justify-content:space-between;gap:6px;font-size:11px;color:var(--muted)}\n.ltxt{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.rules{flex:none;margin:0;padding:6px 8px 6px 22px;border-radius:8px;background:var(--soft);font-size:11px;line-height:1.5;max-height:46%;overflow:auto}\n.list{flex:1 1 auto;min-height:0;overflow:auto;display:grid;grid-template-columns:minmax(0,1fr);gap:5px;align-content:start}\n.row{display:flex;align-items:center;gap:8px;width:100%;min-width:0;padding:7px 9px;text-align:left;border-radius:10px;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink)}\n.rq{flex:1;min-width:0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;font-size:13px}\n.badge{flex:none;padding:2px 8px;border-radius:999px;background:var(--soft);color:var(--ink);font-size:11px;white-space:nowrap}\n.badge.hot{background:var(--accent);color:var(--on-accent)}\n\n.dscroll{flex:1 1 auto;min-height:0;overflow:auto;display:flex;flex-direction:column;gap:8px;padding:10px;border-radius:14px;border:1px solid var(--line);background:var(--panel-paper)}\n.dsec{min-width:0}\n.dsec.ans{padding:8px 10px;border-radius:10px;background:var(--soft)}\n.dsec .txt{font-size:14px}\n.meta{display:grid;grid-template-columns:minmax(0,1fr);gap:4px 12px;padding-top:6px;border-top:1px solid var(--line)}\n.mi{display:flex;justify-content:space-between;gap:8px;min-width:0;font-size:12px}\n.mk{flex:none;color:var(--muted)}\n.mv{min-width:0;text-align:right;overflow-wrap:anywhere}\n\n.fscroll{flex:1 1 auto;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:6px}\n.fl{flex:1 0 auto;min-width:0;display:flex;flex-direction:column;gap:3px;font-size:12px;color:var(--muted)}\n.ta{flex:1 1 auto;width:100%;min-height:44px;resize:none;padding:7px 9px;border-radius:10px;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink);font-size:14px;line-height:1.4}\n.ta::placeholder{color:var(--muted)}\n\n.empty{flex:1 1 auto;min-height:0;overflow:auto;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;padding:6px;text-align:center}\n.mark{width:36px;height:36px;border-radius:50%;background:var(--accent);color:var(--on-accent);display:grid;place-items:center;font-size:18px;font-weight:700}\n.et{font-size:15px;font-weight:700}\n.es{max-width:34em;font-size:12px;color:var(--muted);overflow-wrap:anywhere}\n.ea{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin-top:4px}\n.ea .btn{flex:none}\n\n/* 3x3 */\n.card[data-size=\"3x3\"]{padding:7px;gap:5px}\n.card[data-size=\"3x3\"] .mark,.card[data-size=\"6x3\"] .mark{display:none}\n.card[data-size=\"3x3\"] .tab{height:26px;font-size:11px}\n.card[data-size=\"3x3\"] .tab .n{margin-left:2px;padding:0 3px;min-width:14px;line-height:14px}\n.card[data-size=\"3x3\"] .flash{padding:8px;gap:6px}\n.card[data-size=\"3x3\"] .txt,.card[data-size=\"3x3\"] .fa .txt{font-size:14px}\n.card[data-size=\"3x3\"] .rate .rl{font-size:11px}\n.card[data-size=\"3x3\"] .rate{padding:3px 0}\n.card[data-size=\"3x3\"] .fl>span{display:none}\n.card[data-size=\"3x3\"] .ta{min-height:38px;padding:5px 7px;font-size:13px}\n.card[data-size=\"3x3\"] .btn{min-height:34px;padding:0 6px}\n.card[data-size=\"3x3\"] .et{font-size:14px}\n.card[data-size=\"3x3\"] .ea .btn{min-height:32px}\n.card[data-size=\"3x3\"] .row{padding:6px 8px}\n\n/* 6x3: wide and short */\n.card[data-size=\"6x3\"]{gap:5px}\n.card[data-size=\"6x3\"] .flash.flipped{flex-direction:row;gap:10px}\n.card[data-size=\"6x3\"] .flash.flipped .face{flex:1 1 0;margin:0;align-self:stretch}\n.card[data-size=\"6x3\"] .flash.flipped .fa{align-self:stretch}\n.card[data-size=\"6x3\"] .list{grid-template-columns:repeat(2,minmax(0,1fr))}\n.card[data-size=\"6x3\"] .fscroll{flex-direction:row}\n.card[data-size=\"6x3\"] .fl{flex:1 1 0}\n.card[data-size=\"6x3\"] .ta{min-height:0}\n.card[data-size=\"6x3\"] .meta{grid-template-columns:repeat(2,minmax(0,1fr))}\n.card[data-size=\"6x3\"] .dscroll{flex-direction:row;flex-wrap:wrap}\n.card[data-size=\"6x3\"] .dsec{flex:1 1 40%}\n.card[data-size=\"6x3\"] .meta{flex:1 1 100%}\n\n/* 3x6: narrow and tall */\n.card[data-size=\"3x6\"] .acts.rates{flex-direction:column}\n.card[data-size=\"3x6\"] .rate{flex:none;flex-direction:row;justify-content:space-between;min-height:40px;padding:0 12px}\n.card[data-size=\"3x6\"] .rate .rl{font-size:13px}\n.card[data-size=\"3x6\"] .rate .rs{font-size:12px}\n.card[data-size=\"3x6\"] .txt{font-size:16px}\n.card[data-size=\"3x6\"] .fa .txt{font-size:16px}\n.card[data-size=\"3x6\"] .ta{min-height:96px}\n.card[data-size=\"3x6\"] .fl>span{font-size:11px}\n\n/* 6x6: roomy */\n.card[data-size=\"6x6\"]{padding:14px;gap:10px}\n.card[data-size=\"6x6\"] .tab{height:32px;font-size:13px}\n.card[data-size=\"6x6\"] .flash{padding:16px;gap:12px;border-radius:18px}\n.card[data-size=\"6x6\"] .txt{font-size:22px}\n.card[data-size=\"6x6\"] .flash.flipped .fq .txt{font-size:15px}\n.card[data-size=\"6x6\"] .fa{padding:12px 14px;border-radius:12px}\n.card[data-size=\"6x6\"] .fa .txt{font-size:20px}\n.card[data-size=\"6x6\"] .btn{min-height:44px;font-size:14px}\n.card[data-size=\"6x6\"] .rate{min-height:52px}\n.card[data-size=\"6x6\"] .rate .rl{font-size:15px}\n.card[data-size=\"6x6\"] .rate .rs{font-size:12px}\n.card[data-size=\"6x6\"] .ta{min-height:110px;font-size:16px}\n.card[data-size=\"6x6\"] .list{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}\n.card[data-size=\"6x6\"] .row{padding:10px 12px}\n.card[data-size=\"6x6\"] .rq{font-size:14px}\n.card[data-size=\"6x6\"] .dsec .txt{font-size:18px}\n.card[data-size=\"6x6\"] .meta{grid-template-columns:repeat(2,minmax(0,1fr))}\n.card[data-size=\"6x6\"] .et{font-size:18px}\n.card[data-size=\"6x6\"] .es{font-size:13px}\n.card[data-size=\"6x6\"] .prog,.card[data-size=\"6x6\"] .lhead{font-size:12px}\n";
var LADDER=[3,7,14,30,60];
var RATES=[{key:'again',label:'忘了'},{key:'hard',label:'勉强记得'},{key:'good',label:'记住了'}];
var RESULT_TEXT={again:'忘了',hard:'勉强记得',good:'记住了'};
var RULES=[
  '记住了：升一级，下次间隔依次为 3、7、14、30、60 天',
  '勉强记得：级别不变，间隔缩短为当前间隔的一半（至少 2 天）',
  '忘了：回到第 0 级，明天再复习',
  '新卡片添加当天就会出现在待复习里'
];
function pad2(n){return n<10?'0'+n:''+n}
function fmtDate(d){return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate())}
function addDays(s,n){var p=s.split('-').map(Number);return fmtDate(new Date(p[0],p[1]-1,p[2]+n))}
function diffDays(a,b){
  var x=a.split('-').map(Number),y=b.split('-').map(Number);
  return Math.round((Date.UTC(y[0],y[1]-1,y[2])-Date.UTC(x[0],x[1]-1,x[2]))/86400000);
}
function mdText(s){var p=String(s).split('-');return Number(p[1])+'月'+Number(p[2])+'日'}
function cardsOf(s){return s&&Array.isArray(s.cards)?s.cards:[]}
function dueOf(c){return c.due||'1970-01-01'}
function daysText(n){return n===1?'明天':n+'天后'}
function dueLabel(due,today){
  var d=diffDays(today,due);
  if(d<0)return '逾期'+(-d)+'天';
  if(d===0)return '今天';
  return daysText(d);
}
function byDue(a,b){var x=dueOf(a),y=dueOf(b);return x<y?-1:x>y?1:0}
function plan(c,r,today){
  var L=Math.max(0,Math.min(c.level||0,LADDER.length)),level,days;
  if(r==='good'){level=Math.min(L+1,LADDER.length);days=LADDER[level-1]}
  else if(r==='hard'){level=L;days=L===0?2:Math.max(2,Math.round(LADDER[L-1]/2))}
  else{level=0;days=1}
  return {level:level,days:days,due:addDays(today,days)};
}
function applyRating(c,r,today){
  var p=plan(c,r,today);
  return Object.assign({},c,{
    level:p.level,due:p.due,last:today,lastResult:r,
    reps:(c.reps||0)+1,lapses:(c.lapses||0)+(r==='again'?1:0)
  });
}

function mount(ctx){
  const {root,el,state,ui,update,redraw,uid,day}=ctx;
  const today=day();
  const cards=cardsOf(state);
  if(!ui.view)ui.view='review';
  const due=cards.filter(c=>dueOf(c)<=today).sort(byDue);
  const doneToday=cards.filter(c=>c.last===today).length;
  const h=(tag,attrs,...kids)=>el(tag,attrs||{},...kids.filter(k=>k!==null&&k!==undefined&&k!==false));
  const btn=(cls,label,fn,extra)=>h('button',Object.assign({type:'button',class:cls,onclick:fn},extra||{}),label);
  const go=(v,extra)=>{
    ui.view=v;ui.flipped=false;ui.confirmDel=null;ui.err='';ui.notice='';
    if(extra)Object.assign(ui,extra);
    redraw();
  };
  const openAdd=()=>go('edit',{draft:(ui.draft&&!ui.draft.id)?ui.draft:{q:'',a:''}});
  const flip=()=>{ui.flipped=true;redraw()};

  async function rate(c,r){
    if(ui.busy)return;
    ui.busy=true;
    const prev={level:c.level||0,due:c.due,last:c.last||null,lastResult:c.lastResult||null,reps:c.reps||0,lapses:c.lapses||0};
    const was={flipped:ui.flipped,undo:ui.undo};
    ui.flipped=false;ui.undo={id:c.id,prev:prev};ui.err='';
    try{
      await update(s=>({...s,cards:cardsOf(s).map(x=>x.id===c.id?applyRating(x,r,day()):x)}));
    }catch(e){
      ui.flipped=was.flipped;ui.undo=was.undo;ui.err='保存失败，请再点一次';
    }
    ui.busy=false;redraw();
  }
  async function undo(){
    const u=ui.undo;
    if(!u||ui.busy)return;
    ui.busy=true;ui.undo=null;ui.flipped=false;
    try{
      await update(s=>({...s,cards:cardsOf(s).map(x=>x.id===u.id?Object.assign({},x,u.prev):x)}));
    }catch(e){
      ui.undo=u;ui.err='撤销失败，请再试一次';
    }
    ui.busy=false;redraw();
  }

  function box(title,sub,actions,mark){
    return h('div',{class:'empty'},
      mark?h('div',{class:'mark'},'✓'):null,
      h('div',{class:'et'},title),
      h('div',{class:'es'},sub),
      h('div',{class:'ea'},...actions));
  }
  function progress(){
    const total=doneToday+due.length;
    const bar=h('i',{class:'bar'});
    const fill=h('b',{});
    fill.style.width=(total?Math.round(doneToday/total*100):0)+'%';
    bar.append(fill);
    return h('div',{class:'prog'},
      h('span',{class:'ptxt'},'今天 '+doneToday+'/'+total),
      bar,
      ui.undo?btn('link','撤销',undo,{'aria-label':'撤销上一次评分'}):null);
  }
  function reviewView(){
    if(!cards.length){
      return h('div',{class:'body'},box('还没有卡片','先写下一个问题和它的答案，之后打开就会先看到今天该复习的。',[btn('btn main','添加第一张',openAdd)],false));
    }
    if(!due.length){
      const up=cards.filter(c=>dueOf(c)>today).sort(byDue);
      const nd=dueOf(up[0]);
      const nn=up.filter(c=>dueOf(c)===nd).length;
      return h('div',{class:'body'},progress(),
        box(doneToday?'今天的复习完成了':'今天没有要复习的卡片',
          '下次复习：'+dueLabel(nd,today)+'（'+mdText(nd)+'），'+nn+' 张',
          [btn('btn main','添加卡片',openAdd),btn('btn','全部卡片',()=>go('list'))],true));
    }
    const c=due[0];
    const fa={class:'flash'+(ui.flipped?' flipped':'')};
    if(!ui.flipped)fa.onclick=flip;
    const flash=h('div',fa,
      h('section',{class:'face fq'},h('span',{class:'tag'},'题目'),h('div',{class:'txt'},c.q)),
      ui.flipped?h('section',{class:'face fa'},h('span',{class:'tag'},'答案'),h('div',{class:'txt'},c.a)):null,
      ui.flipped?null:h('div',{class:'hint'},'先想一想，再翻开答案'));
    const acts=ui.flipped
      ?h('div',{class:'acts rates'},...RATES.map(r=>{
          const p=plan(c,r.key,today);
          return h('button',{type:'button',class:'btn rate '+r.key,onclick:()=>rate(c,r.key),
            'aria-label':r.label+'，'+daysText(p.days)+'再复习（'+mdText(p.due)+'）'},
            h('span',{class:'rl'},r.label),h('span',{class:'rs'},daysText(p.days)));
        }))
      :h('div',{class:'acts'},btn('btn main grow','翻开答案',flip));
    return h('div',{class:'body'},progress(),flash,acts);
  }


  function listView(){
    if(!cards.length){
      return h('div',{class:'body'},box('还没有卡片','点「添加」写下第一个问题和答案。',[btn('btn main','添加第一张',openAdd)],false));
    }
    const sorted=cards.slice().sort(byDue);
    const head=h('div',{class:'lhead'},
      h('span',{class:'ltxt'},'共 '+cards.length+' 张 · 今天待复习 '+due.length+' 张'),
      btn('link',ui.showRules?'收起规则':'复习规则',()=>{ui.showRules=!ui.showRules;redraw()}));
    const rules=ui.showRules?h('ul',{class:'rules'},...RULES.map(t=>h('li',{},t))):null;
    const rows=sorted.map(c=>{
      const dl=dueOf(c);
      return h('button',{type:'button',class:'row',onclick:()=>go('detail',{sel:c.id})},
        h('span',{class:'rq'},c.q),
        h('span',{class:'badge'+(dl<=today?' hot':'')},dueLabel(dl,today)));
    });
    return h('div',{class:'body'},head,rules,h('div',{class:'list'},...rows));
  }

  async function del(id){
    if(ui.busy)return;
    ui.busy=true;
    const was={view:ui.view,sel:ui.sel,confirmDel:ui.confirmDel};
    ui.view='list';ui.sel=null;ui.confirmDel=null;ui.err='';
    try{
      await update(s=>({...s,cards:cardsOf(s).filter(x=>x.id!==id)}));
    }catch(e){
      Object.assign(ui,was);ui.err='删除失败，请再试一次';
    }
    ui.busy=false;redraw();
  }
  function metaItem(k,v){return h('div',{class:'mi'},h('span',{class:'mk'},k),h('span',{class:'mv'},v))}
  function detailView(){
    const c=cards.find(x=>x.id===ui.sel);
    if(!c)return listView();
    const dl=dueOf(c);
    const meta=h('div',{class:'meta'},
      metaItem('下次复习',mdText(dl)+'（'+dueLabel(dl,today)+'）'),
      metaItem('熟练度',(c.level||0)+' / 5 级'),
      metaItem('复习次数',(c.reps||0)+' 次'),
      metaItem('忘记次数',(c.lapses||0)+' 次'),
      metaItem('上次',c.last?mdText(c.last)+' '+(RESULT_TEXT[c.lastResult]||''):'还没复习过'));
    const scroll=h('div',{class:'dscroll'},
      h('section',{class:'dsec'},h('span',{class:'tag'},'题目'),h('div',{class:'txt'},c.q)),
      h('section',{class:'dsec ans'},h('span',{class:'tag'},'答案'),h('div',{class:'txt'},c.a)),
      meta);
    const acts=ui.confirmDel===c.id
      ?h('div',{class:'acts'},
          h('span',{class:'ask'},'确定删除？'),
          btn('btn grow','取消',()=>{ui.confirmDel=null;redraw()}),
          btn('btn grow strong','确认删除',()=>del(c.id)))
      :h('div',{class:'acts'},
          btn('btn grow','返回',()=>go('list')),
